<script>import { englishGuides } from '$lib/content/guides-en.js'; let { data } = $props(); const guide = $derived(data.guide); const canonical = $derived(`https://synvox.pro/en/guides/${guide.slug}/`); const schema = $derived({ '@context': 'https://schema.org', '@type': 'Article', headline: guide.title, description: guide.description, inLanguage: 'en', mainEntityOfPage: canonical, author: { '@type': 'Organization', name: 'SYNVOX', url: 'https://synvox.pro/en/' } });</script>
<svelte:head><title>{guide.title} — SYNVOX</title><meta name="description" content={guide.description} /><link rel="canonical" href={canonical} /><meta property="og:type" content="article" /><meta property="og:locale" content="en_US" /><meta property="og:title" content={`${guide.title} — SYNVOX`} /><meta property="og:description" content={guide.description} />{@html `<script type="application/ld+json">${JSON.stringify(schema).replace(/</g, '\\u003c')}</script>`}</svelte:head>
<main id="main" class="guide-page section-shell"><nav class="guide-breadcrumb" aria-label="Breadcrumb"><a href="/en/">SYNVOX</a><span aria-hidden="true"> / </span><a href="/en/#guides">AI guides</a></nav><article><p class="section-index">PRACTICE · SYNVOX</p><h1>{guide.title}</h1><p class="guide-lead">{guide.lead}</p><p class="guide-byline">A SYNVOX guide · Alpha product in development</p>{#each guide.sections as section}<section class="guide-section"><h2>{section.title}</h2><p>{section.text}</p></section>{/each}<section class="guide-example"><h2>An example task for AI</h2><blockquote>{guide.example}</blockquote><p>This is a task-framing example, not a report of completed work.</p></section><section class="guide-section"><h2>Common questions</h2>{#each guide.questions as item}<details class="guide-question"><summary>{item.q}</summary><p>{item.a}</p></details>{/each}</section></article><aside class="guide-section" aria-label="Continue reading"><h2>Other guides</h2>{#each englishGuides.filter((item) => item.slug !== guide.slug) as item}<a class="guide-related" href={`/en/guides/${item.slug}/`}>{item.title} <span aria-hidden="true">↗</span></a>{/each}</aside><div class="guide-actions"><a class="button button-primary" href="/en/#download">Download SYNVOX for free</a><a class="button button-quiet" href="/en/documents/">Legal archive</a></div></main>
